[{"order":1,"type":"heading","text":"Understanding Application-Level vs Router-Level Middleware in Express.js"},{"order":2,"type":"paragraph","text":"Middleware functions are the backbone of any Express.js application. They are functions that have access to the request object (req), the response object (res), and the next middleware function in the application's request-response cycle. Understanding how to scope and apply middleware effectively is crucial for building scalable Node.js applications."},{"order":3,"type":"heading","text":"What is Application-Level Middleware?"},{"order":4,"type":"paragraph","text":"Application-level middleware is bound to an instance of the Express object using 'app.use()' or HTTP method functions like 'app.get()'. This type of middleware executes for every HTTP request that hits the application, making it ideal for global tasks such as logging, parsing request bodies, or handling global security headers."},{"order":5,"type":"code","text":"const express = require('express');
const app = express();

// Application-level middleware for logging
app.use((req, res, next) => {
  console.log('Global Request URL:', req.url);
  next();
});

app.get('/', (req, res) => {
  res.send('Hello World');
});

app.listen(3000);"},{"order":6,"type":"heading","text":"What is Router-Level Middleware?"},{"order":7,"type":"paragraph","text":"Router-level middleware works identically to application-level middleware, but it is bound to an instance of 'express.Router()'. This allows you to modularize your routing logic and apply middleware only to specific route paths or sub-routers, such as '/api/v1/users'."},{"order":8,"type":"code","text":"const express = require('express');
const router = express.Router();

// Router-level middleware for authentication on this router only
router.use((req, res, next) => {
  console.log('Auth check for router subpath');
  next();
});

router.get('/profile', (req, res) => {
  res.send('User Profile');
});

// Mount the router on the app
const app = express();
app.use('/api', router);
app.listen(3000);"},{"order":9,"type":"heading","text":"Key Differences and Use Cases"},{"order":10,"type":"bullet_point","text":"Scope: Application-level middleware runs for every route in the app, whereas router-level middleware runs only on routes attached to that specific router instance."},{"order":11,"type":"bullet_point","text":"Modularity: Router-level middleware is essential for large-scale applications where you need to group routes into separate files or modules."},{"order":12,"type":"bullet_point","text":"Execution Order: Both follow the order in which they are defined in the code, but application-level middleware always intercepts the request before router-level middleware."}]
